use std::io::{self, Read};

trait Pricing {
    fn total(&self, qty: u64, unit: u64) -> u64;
}

struct Plain;
struct Bulk;
struct Member;

impl Pricing for Plain {
    fn total(&self, qty: u64, unit: u64) -> u64 {
        qty * unit
    }
}

impl Pricing for Bulk {
    fn total(&self, qty: u64, unit: u64) -> u64 {
        let t = qty * unit;
        if qty >= 10 {
            t - t * 10 / 100
        } else {
            t
        }
    }
}

impl Pricing for Member {
    fn total(&self, qty: u64, unit: u64) -> u64 {
        let t = qty * unit;
        let mut r = t - t * 5 / 100;
        if qty >= 3 {
            r = r.saturating_sub(100);
        }
        r
    }
}

fn fmt(c: u64) -> String {
    format!("${}.{:02}", c / 100, c % 100)
}

fn main() {
    let mut s = String::new();
    io::stdin().read_to_string(&mut s).unwrap();
    let mut sum = 0u64;
    for line in s.lines() {
        let p: Vec<&str> = line.split_whitespace().collect();
        if p.is_empty() {
            continue;
        }
        let name = p[0];
        let qty: u64 = p.get(1).and_then(|x| x.parse().ok()).unwrap_or(0);
        let unit: u64 = p.get(2).and_then(|x| x.parse().ok()).unwrap_or(0);
        let kind: Option<Box<dyn Pricing>> = match p.get(3).copied() {
            Some("plain") => Some(Box::new(Plain)),
            Some("bulk") => Some(Box::new(Bulk)),
            Some("member") => Some(Box::new(Member)),
            _ => None,
        };
        match kind {
            Some(k) => {
                let t = k.total(qty, unit);
                sum += t;
                println!("{} {}", name, fmt(t));
            }
            None => println!("{} invalid kind", name),
        }
    }
    println!("total {}", fmt(sum));
}

